script.text:

function load$GridVoucherDetail$(g) {
	g.add_itemValueChanged(onChange$GridVoucherDetail$);
	g.add_onResponseComplete(on$GridVoucherDetail$ResponseComplete);
	g.add_commandEvent(on$GridVoucherDetail$ExecuteCommand);
	&FormulaExpression;
	&ESG.LoadScriptHoverField;
	g.$h = ['ma_dvcs', 'stt_rec', 'ngay_lct', 'loai_ct', 'ma_nt'];
	udf$Detail$(g);
	udf$Detail$PaymentControl(g);
}
/* <flatten type="Javascript"> */
function udf$Detail$PaymentControl(g) {
	if (!g.get_element().parentForm._udfPaymentControl) {
		udf$Field$(g, 'ma_tt');
		udf$Field$(g, 'so_ct0');
		udf$Field$(g, 'ngay_ct0');
	}
}
function dispose$GridVoucherDetail$(g) {
	g.$a = null;
	try {g.remove_commandEvent(on$GridVoucherDetail$ExecuteCommand);} catch (ex) {}
	try {g.remove_itemValueChanged(onChange$GridVoucherDetail$);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridVoucherDetail$ResponseComplete);} catch (ex) {}
}
function onChange$GridVoucherDetail$Account(o) {o.grid.request(o, 'Account', 'Account', ['tk'], o);}
function onChange$GridVoucherDetail$Customer(o) {
	var g = o.grid;
	g.setItemGridBehavior(o, [
		['stt_rec_tt2', '', '', false], ['so_ct_tt2', '', '', false], ['ma_nt_tt2', '', '', false], ['ngay_ct_tt2', null, '', false],
		['stt_rec_tt3', '', '', false], ['so_ct_tt3', '', '', false], ['ma_nt_tt3', '', '', false], ['ngay_ct_tt3', null, '', false]
	]);
}
function onChange$GridVoucherDetail$(sender, eventArgs) {
	var o = eventArgs.get_object(), g = o.grid, f = g.get_element().parentForm, name = o.field.Name;
	switch (name) {
		case 'ps_no_nt':
			g.executeExpression(o, ['[ps_co_nt]:=0']);
			g.validExpression(o, [g.$a.ps_no, g.$a.ps_co], [g.$a.t_ps_no_nt, g.$a.t_ps_co_nt, g.$a.t_ps_no, g.$a.t_ps_co], null, 'ps_co_nt');
			break;
		case 'ps_co_nt':
			g.executeExpression(o, ['[ps_no_nt]:=0']);
			g.validExpression(o, [g.$a.ps_co, g.$a.ps_no], [g.$a.t_ps_no_nt, g.$a.t_ps_co_nt, g.$a.t_ps_no, g.$a.t_ps_co], null, null);
			break;
		case 'ps_no':
			g.executeExpression(o, ['[ps_co]:=0']);
			g.validExpression(o, null, [g.$a.t_ps_no, g.$a.t_ps_co], null, 'ps_co');
			break;
		case 'ps_co':
			g.executeExpression(o, ['[ps_no]:=0']);
			g.validExpression(o, null, [g.$a.t_ps_no, g.$a.t_ps_co], null, null);
			break;
		default:
			break;
	}
}
/* </flatten> */
function on$GridVoucherDetail$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm;
	switch (action) {
		&Clipboard.Event.Before;
		&Clipboard.Event.Before.Request;
		&Clipboard.Event.Before.Process;
		&Clipboard.Event.After;
		&Clipboard.Event.After.Process;
		case 'AfterRemoveRow':
			on$GridVoucherDetail$RowChange(g, f);
			break;
		case 'AfterCloneRow':
			g.setItemFieldValue('stt_rec0', e.type.Value, '');
			on$GridVoucherDetail$RowChange(g, f);
			break;
		case 'AfterInsertRow':
			if (g._rowCount > 1) {
				var d1 = f.getItemValue('t_ps_no_nt') - f.getItemValue('t_ps_co_nt'), d2 = f.getItemValue('t_ps_no') - f.getItemValue('t_ps_co'), activeRow = g._activeRow;
				if (d1 > 0) {
					g._setItemValue(activeRow, g._getColumnOrder('ps_co_nt'), d1);
					g._setItemValue(activeRow, g._getColumnOrder('ps_co'), d2);
				}
				else {
					g._setItemValue(activeRow, g._getColumnOrder('ps_no_nt'), -d1);
					g._setItemValue(activeRow, g._getColumnOrder('ps_no'), -d2);
				}
				on$GridVoucherDetail$RowChange(g, f);
			}
			break;
		case 'Check':
			&ESG.ScriptCheck;
			g.validRowExpression('ma_kh', '(![tk_cn]) || ([ma_kh] != "")');

			break;
		case 'ImportData':
			if (f._action == 'View') break;
			&ImportDetailImportDataCommand;;
			break;
		case 'Download':
			&UserDefinedDownload;
			break;
&GridExtraToolbarExecuteCommandScript;;
		default:
			break;
	}
}
function on$GridVoucherDetail$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
	switch (context) {
	 case 'Account':
			g.setItemGridBehavior(o, [
				['tk_cn', result[0].Value, '', false], ['kieu_tk', result[1].Value, '', false],
				['stt_rec_tt2', '', '', false], ['so_ct_tt2', '', '', false], ['ma_nt_tt2', '', '', false], ['ngay_ct_tt2', null, '', false],
				['stt_rec_tt3', '', '', false], ['so_ct_tt3', '', '', false], ['ma_nt_tt3', '', '', false], ['ngay_ct_tt3', null, '', false]
			]);
			break;
		case 'ARInvoiceNumber':
			g.setItemGridBehavior(o, [
				['ngay_ct_tt2', result[0].Value, '', false], ['ma_nt_tt2', result[1].Value, '', false],
				['stt_rec_tt3', '', '', false], ['so_ct_tt3', '', '', false], ['ma_nt_tt3', '', '', false], ['ngay_ct_tt3', null, '', false]
			]);
			break;
		case 'APInvoiceNumber':
			g.setItemGridBehavior(o, [
				['ngay_ct_tt3', result[0].Value, '', false], ['ma_nt_tt3', result[1].Value, '', false],
				['stt_rec_tt2', '', '', false], ['so_ct_tt2', '', '', false], ['ma_nt_tt2', '', '', false], ['ngay_ct_tt2', null, '', false]
			]);
			break;
		case 'Download':
			g._key = result[0].Value;
			break;
		&ESG.ScriptGridResponse;
		default:
			break;
	}
}
/* <flatten type="Javascript"> */
function on$GridVoucherDetail$RowChange(g, f) {g.executeAggregate([g.$a.t_ps_no_nt, g.$a.t_ps_co_nt, g.$a.t_ps_no, g.$a.t_ps_co]);}
function onChange$GridVoucherDetail$ARInvoiceNumber(o) {o.grid.request(o, 'ARInvoiceNumber', 'ARInvoiceNumber', ['so_ct_tt2', 'stt_rec_tt2', 'ma_kh'], o.grid.$h, true);}
function onChange$GridVoucherDetail$APInvoiceNumber(o) {o.grid.request(o, 'APInvoiceNumber', 'APInvoiceNumber', ['so_ct_tt3', 'stt_rec_tt3', 'ma_kh'], o.grid.$h, true);}
function onFocus$GridVoucherDetail$InvoiceNumber(o) {
	var g = $find(o.id.split('_inputCell_')[0]);

	g._enter(o);
	var f = g.get_element().parentForm;
	if (f._action == 'New' || f._action == 'Edit') o._controlBehavior.add_loading(on$Filter$Before$Loading);
}
function on$Filter$Before$Loading(sender, e) {
	var g = sender._element.grid, f = g.get_element().parentForm;

	a = [
		{Name: 'ma_dvcs', Type: 'String', Value: f.getItemValue('ma_dvcs')},
		{Name: 'stt_rec', Type: 'String', Value: f.getItemValue('stt_rec')},
		{Name: 'ngay_lct', Type: 'DateTime', Value: f.getItemValue('ngay_lct')},
		{Name: 'loai_ct', Type: 'String', Value: f.getItemValue('loai_ct')},
		{Name: 'ma_nt', Type: 'String', Value: f.getItemValue('ma_nt')},
		{Name: 'tk', Type: 'String', Value: g._getItemValue(g._activeRow, g._getColumnOrder('tk'))},
		{Name: 'ma_kh', Type: 'String', Value: g._getItemValue(g._activeRow, g._getColumnOrder('ma_kh'))}
	];
	sender.set_memvars(a);
}
/* </flatten> */

			&ImportDetailInsertResult;
			&ImportDetailScript;
			&DowloadScript;
			&GridExtraToolbarScript;
			&ESG.GridScript;
